import json, time, urllib.request, boto3
def handler(event, context):
    reason = None
    if event['RequestType'] == 'Create':
        try:
            reason = check(event['ResourceProperties'])
        except Exception as e:
            reason = 'cdkpf probe could not run: %r' % e
    body = {'Status': 'FAILED' if reason else 'SUCCESS', 'Reason': (reason or 'ok')[:900],
            'PhysicalResourceId': event.get('PhysicalResourceId', context.log_stream_name),
            'StackId': event['StackId'], 'RequestId': event['RequestId'], 'LogicalResourceId': event['LogicalResourceId']}
    urllib.request.urlopen(urllib.request.Request(event['ResponseURL'], data=json.dumps(body).encode(), method='PUT', headers={'Content-Type': ''}))
def check(p):
    sqs = boto3.client('sqs')
    want = set()
    if p.get('TopicArn'):
        boto3.client('sns').publish(TopicArn=p['TopicArn'], Message='cdkpf-sns')
        want.add('SNS')
    if p.get('EventSource'):
        boto3.client('events').put_events(Entries=[{'Source': p['EventSource'], 'DetailType': 'probe', 'Detail': '{}'}])
        want.add('EventBridge')
    alarm = p.get('AlarmName')
    if alarm:
        boto3.client('cloudwatch').set_alarm_state(AlarmName=alarm, StateValue='ALARM', StateReason='cdkpf probe')
    got, deadline = set(), time.time() + 90
    while time.time() < deadline and want - got:
        for m in sqs.receive_message(QueueUrl=p['QueueUrl'], WaitTimeSeconds=10, MaxNumberOfMessages=10).get('Messages', []):
            got.add('EventBridge' if p.get('EventSource', '-') in m['Body'] else 'SNS')
    bad = ['%s message was not delivered within 90 s' % s for s in sorted(want - got)]
    if alarm:
        for _ in range(12):
            h = boto3.client('cloudwatch').describe_alarm_history(AlarmName=alarm, HistoryItemType='Action')['AlarmHistoryItems']
            if h:
                break
            time.sleep(5)
        failed = [i['HistorySummary'] + ' ' + i.get('HistoryData', '')[:300] for i in h if not i['HistorySummary'].startswith('Successfully')]
        bad = failed + bad + ([] if h else ['no alarm action ran within 60 s'])
    return '; '.join(bad)
